#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 1e4 + 5;
int n, m, color[MAX_N], isBipartite;
vector<int> graph[MAX_N];
void dfs(int vertex) {
    for (auto neighbor: graph[vertex])
        if (!color[neighbor]) {
            color[neighbor] = 3 — color[vertex];
            dfs(neighbor);
        } else if (color[neighbor] + color[vertex] != 3)
            isBipartite = 0;
}
void solve() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        graph[i].clear();
        color[i] = 0;
    }
    for (int i = 1; i <= m; i++) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    isBipartite = 1;
    color[1] = 1;
    dfs(1);
    if (!isBipartite) {
        cout << "Alice" << endl;
        for (int i = 1; i <= n; i++) {
            cout << 1 << ' ' << 2 << endl;
            int vertex, chosenColor;
            cin >> vertex >> chosenColor;
        }
    } else {
        cout << "Bob" << endl;
        vector<int> part1, part2;
        for (int i = 1; i <= n; i++)
            if (color[i] == 1)
                part1.push_back(i);
            else
                part2.push_back(i);
        for (int i = 1; i <= n; i++) {
            int color1, color2;
            cin >> color1 >> color2;
            if ((color1 == 1 || color2 == 1) && part1.size()) {
                cout << part1.back() << ' ' << 1 << endl;
                part1.pop_back();
            } else if ((color1 == 2 || color2 == 2) && part2.size()) {
                cout << part2.back() << ' ' << 2 << endl;
                part2.pop_back();
            } else if (!part1.size()) {
                int chosenColor = (color1 == 1 ? color2 : color1);
                cout << part2.back() << ' ' << chosenColor << endl;
                part2.pop_back();
            } else {
                int chosenColor = (color1 == 2 ? color2 : color1);
                cout << part1.back() << ' ' << chosenColor << endl;
                part1.pop_back();
            }
        }
    }
}
int main() {
    int t;
    cin >> t;
    while (t--)
        solve();
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 1e5 + 5;
int n, q, a[MAX_N], p[MAX_N];
bool canFormTwoTriangles(int l, int r) {
    int t = 0;
    for (int i = l; i <= r; i++)
        p[++t] = a[i];
    sort(p + 1, p + t + 1);
    for (int i = 1; i <= t - 5; i++)
        for (int j = i + 1; j <= i + 5; j++)
            for (int k = j + 1; k <= i + 5; k++) {
                int q[4], c = 0;
                for (int m = i + 1; m <= i + 5; m++)
                    if (m != j && m != k)
                        q[++c] = p[m];
                if (p[i] + p[j] > p[k] && q[1] + q[2] > q[3])
                    return true;
            }
    int triangleCount = 0;
    for (int i = 1; i <= t - 2; i++)
        if (p[i] + p[i + 1] > p[i + 2]) {
            i += 2;
            triangleCount++;
        }
    return triangleCount > 1;
}
int main() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    while (q--) {
        int l, r;
        cin >> l >> r;
        if (r — l + 1 >= 48 || canFormTwoTriangles(l, r))
            cout << "YES" << '\n';
        else
            cout << "NO" << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_SIZE = 105;
char operationType;
int n, m, k, q, grid[MAX_SIZE][MAX_SIZE];
string s;
int calculateSum(int x1, int y1, int x2, int y2) {
    int sum = 0;
    for (int i = x1; i <= x2; i++)
        for (int j = y1; j <= y2; j++)
            sum += grid[i][j];
    return sum;
}
void performOperation(int x, int y) {
    cout << x << ' ' << y << '\n';
    for (int i = 1; i <= k; i++) {
        grid[x][y] = 1;
        if (operationType == 'H')
            y++;
        else
            x++;
    }
    int rowSums[MAX_SIZE] = {}, colSums[MAX_SIZE] = {};
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            rowSums[i] += grid[i][j];
            colSums[j] += grid[i][j];
        }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (rowSums[i] == m || colSums[j] == n)
                grid[i][j] = 0;
}
void solve() {
    cin >> n >> m >> k >> q >> s;
    s = ' ' + s;
    memset(grid, 0, sizeof(grid));
    for (int i = 1; i <= q; i++) {
        operationType = s[i];
        if (operationType == 'H') {
            int row = -1;
            for (int j = 1; j <= n; j++)
                if (calculateSum(j, 1, j, k) == 0) {
                    row = j;
                    if (calculateSum(j, 1, j, m) == m - k) {
                        break;
                    }
                }
            performOperation(row, 1);
        } else {
            int col = -1;
            for (int j = 1; j <= m; j++)
                if (calculateSum(1, j, k, j) == 0) {
                    col = j;
                    if (calculateSum(1, j, n, j) == n - k) {
                        break;
                    }
                }
            performOperation(1, col);
        }
    }
}
int main() {
    int t;
    cin >> t;
    while (t--)
        solve();
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 2e5 + 5;
bitset<MAX_N + 1> isComposite, isWinning, isPrimeLosing, isPrimeWinning, isGoodPosition;
void initialize() {
    isComposite[1] = true;
    for (int i = 2; i <= MAX_N; i++)
        for (int j = 2 * i; j <= MAX_N; j += i)
            isComposite[j] = true;
    for (int i = 3; i <= MAX_N; i += 2) {
        int count = 0, j = i;
        while (!isComposite[j - 2]) {
            count++;
            j -= 2;
        }
        isWinning[i] = count % 2;
        isPrimeLosing[i] = !isComposite[i] && !isWinning[i];
    }
    isWinning[4] = true;
    for (int i = 3; i <= MAX_N; i += 2)
        if (isPrimeLosing[i])
            isWinning |= isPrimeLosing << i;
    for (int i = 1; i <= MAX_N; ++i)
        isPrimeWinning[i] = (i % 2) && isWinning[i] && !isComposite[i];
    for (int i = 3; i <= MAX_N; i += 2)
        if (isPrimeWinning[i])
            isGoodPosition |= isPrimeWinning << i;
}
void solve() {
    int n, x, totalWinning = 0, totalGood = 0;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> x;
        totalWinning += isWinning[x];
        totalGood += isGoodPosition[x];
    }
    if (totalWinning <= n - n % 2)
        cout << (totalWinning ? "Alice" : "Bob") << endl;
    else
        cout << (totalGood && totalGood < n ? "Alice" : "Bob") << endl;
}
int main() {
    initialize();
    int t;
    cin >> t;
    while (t--)
        solve();
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 15, dx[] = {-1, 0, 0, 1}, dy[] = {0, -1, 1, 0};
int n, m, x, y, grid[MAX_N][MAX_N], color[MAX_N][MAX_N], visited[MAX_N][MAX_N], currentValue, currentColor, flipCoords;
bool isAdjacent(int x, int y) {
    int nx, ny;
    for (int i = 0; i < 4; i++) {
        nx = x + dx[i];
        ny = y + dy[i];
        if (1 <= nx && nx <= n && 1 <= ny && ny <= m && visited[nx][ny])
            return true;
    }
    return false;
}
void interact() {
    cin >> x >> y;
    if (flipCoords)
        swap(x, y);
    visited[x][y] = 1;
}
void output(int x, int y) {
    visited[x][y] = 1;
    if (flipCoords)
        cout << y << ' ' << x << endl;
    else
        cout << x << ' ' << y << endl;
}
void placePair(int x1, int y1, int x2, int y2) {
    grid[x1][y1] = ++currentValue;
    grid[x2][y2] = ++currentValue;
    color[x1][y1] = color[x2][y2] = ++currentColor;
}
void placeTShape(int x, int y) {
    int largestValue = n * m - 12 + currentColor * 3;
    grid[x][y] = ++currentValue;
    color[x][y] = ++currentColor;
    int nx, ny;
    for (int i = 0; i < 4; i++) {
        nx = x + dx[i];
        ny = y + dy[i];
        if (1 <= nx && nx <= n && 1 <= ny && ny <= m) {
            grid[nx][ny] = ++largestValue;
            color[nx][ny] = currentColor;
        }
    }
}
void printGrid() {
    if (!flipCoords)
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                cout << grid[i][j] << ' ';
            }
            cout << endl;
        }
    else
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                cout << grid[j][i] << ' ';
            }
            cout << endl;
        }
}
void fillHorizontalPairs() {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < m; j++)
            if (!grid[i][j] && !grid[i][j + 1])
                placePair(i, j, i, j + 1);
}
void fillVerticalPairs() {
    for (int i = 1; i < n; i++)
        for (int j = 1; j <= m; j++)
            if (!grid[i][j] && !grid[i + 1][j])
                placePair(i, j, i + 1, j);
}
void solve() {
    cin >> n >> m;
    memset(grid, 0, sizeof(grid));
    memset(color, 0, sizeof(color));
    memset(visited, 0, sizeof(visited));
    currentColor = currentValue = flipCoords = 0;
    if (n % 2 == 1 && m % 2 == 1) {
        for (int i = 1; i <= n; i++)
            for (int j = 1; j < m; j += 2)
                placePair(i, j, i, j + 1);
        for (int i = 1; i <= n; i += 2)
            placePair(i, m, i + 1, m);
        grid[n][m] = n * m;
        printGrid();
        for (int i = 1; i < n * m; i += 2) {
            interact();
            bool selected = false;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++)
                    if (!visited[i][j] && color[i][j] == color[x][y]) {
                        output(i, j);
                        selected = true;
                        break;
                    }
                if (selected)
                    break;
            }
            if (selected)
                continue;
            for (int i = 1; i <= n; i++)
                for (int j = 1; j <= m; j++)
                    if (!visited[i][j] && isAdjacent(i, j) && grid[i][j] != n * m) {
                        output(i, j);
                        i = n;
                        j = m;
                    }
        }
        cin >> x >> y;
        return;
    }
    if (n > m) {
        swap(n, m);
        flipCoords = 1;
    }
    if (n == 4 && m == 4) {
        placeTShape(1, 2);
        placeTShape(2, 4);
        placeTShape(3, 1);
        placeTShape(4, 3);
    } else if (n == 4 && m == 5) {
        placeTShape(1, 2);
        placeTShape(3, 1);
        placeTShape(3, 5);
        placeTShape(4, 3);
        fillHorizontalPairs();
    } else {
        placeTShape(1, 2);
        placeTShape(3, 1);
        placeTShape(1, m — 1);
        placeTShape(3, m);
        placePair(2, 3, 3, 3);
        placePair(4, 2, 4, 3);
        placePair(2, m — 2, 3, m — 2);
        placePair(4, m — 2, 4, m — 1);
        if (m % 2 == 0)
            fillHorizontalPairs();
        else
            fillVerticalPairs();
    }
    printGrid();
    for (int i = 1; i <= n * m; i += 2) {
        interact();
        pair bestMove = {-1,-1};
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                if (!visited[i][j] && color[i][j] == color[x][y] && (bestMove.first == -1 || grid[i][j] < grid[bestMove.first][bestMove.second]))
                    bestMove = {i,j};
        output(bestMove.first, bestMove.second);
    }
}
int main() {
    int t;
    cin >> t;
    while (t--)
        solve();
}
